cd /home/dev/garden && python3 - <<'PY'
# Pure-python equivalent of tools/check_site.py (PyYAML absent in this sandbox).
# Mirrors its logic 1:1: required front-matter fields per layer, summary <= 200 words,
# exactly one project page, series name must exist, parent updated >= child updated.
import datetime, glob, os, re
from pathlib import Path

ROOT = Path(__file__).parent if "__file__" in dir() else Path.cwd()
SITE = ROOT / "site"
MAX_WORDS = 200
required = {
    "project": ["title", "summary"],
    "series": ["title", "summary", "series"],
    "experiment": ["title", "summary", "date", "updated", "tldr"],
}
layers = {"project", "series", "experiment"}
errors = []

def parse_fm(path):
    txt = path.read_text(encoding="utf-8")
    m = re.match(r"---\n(.*?)\n---\n", txt, re.S)
    if not m:
        return {}
    fm, block, cur = {}, {}, None
    for line in m.group(1).splitlines():
        key_m = re.match(r"([a-z]+):\s*(.*)", line)
        if key_m:
            cur = key_m.group(1)
            fm[cur] = key_m.group(2).strip()
            if key_m.group(2).strip() == "|":
                block = cur
            continue
        if cur in fm and fm[cur] == "|" and not line.startswith("  "):
            # top-level key without block scalar; not needed for this subset
            pass
        if cur and fm.get(cur) == "|" and line.startswith("  "):
            # append to block (only summary matters; word count below)
            if cur == "summary":
                pass
        # accumulate block scalars
        if cur and line.startswith("  ") and cur == "summary" and fm.get(cur) == "|":
            if "summary_text" not in fm:
                fm["_summary_lines"] = []
            fm["_summary_lines"].append(line)
            continue
        if line.strip():
            key_m2 = re.match(r"([a-z]+):", line)
            if key_m2 and key_m2.group(1) != "summary" and not line.startswith("  "):
                cur = key_m2.group(1)
    if cur == "summary" and fm.get("summary") == "|":
        pass
    return fm

# Simpler and more faithful: parse block scalars explicitly.
def parse_frontmatter(path):
    txt = path.read_text(encoding="utf-8")
    m = re.match(r"^---\n(.*?)\n---\n", txt, re.S)
    if not m:
        return None
    fm = {}
    lines = m.group(1).splitlines()
